//! Explicit native tracked FIX adapter. Default legacy dispatch is untouched.
use super::{capture_command,policy_stdout_work,bounded,NativeReportWork,OUTER_WATCHDOG,MAX_STDERR};use crate::{native_fix_wire::{Terminal,Mode},selected_exclusions_wire::MAX_HEADER,report_work::Work};use std::{io::{self,Write},path::PathBuf,process::Command};
fn invalid(text:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,text)}
#[derive(Debug,PartialEq,Eq)]struct Invocation{program:PathBuf,root:PathBuf,prefixes:Vec<String>,apply:bool,mode:Mode}
fn invocation(args:&[String])->io::Result<Invocation>{
 let mut ordinary=vec!["analyze".to_owned()];let(mut program,mut i)=(None,0);while let Some(arg)=args.get(i){i+=1;if arg=="--native-dmbc"{let path=PathBuf::from(args.get(i).ok_or_else(||invalid("native FIX compiler executable missing"))?);i+=1;if !path.is_absolute()||program.replace(path).is_some(){return Err(invalid("native FIX requires one absolute compiler executable"))}}else{ordinary.push(arg.clone())}}
 let parsed=crate::cli_arguments::parse(ordinary);if parsed.cmd!="fix"{return Err(invalid("native FIX route accepts only the original fix command"))}let(mut prefixes,mut apply,mut tests,mut drop_declared,mut i)=(Vec::new(),false,false,false,0);while let Some(flag)=parsed.flags.get(i){i+=1;match flag.as_str(){"--path"=>{let path=parsed.flags.get(i).ok_or_else(||invalid("native FIX exact path missing"))?;i+=1;prefixes.push(path.clone());},"--apply"=>apply=true,"--tests"=>tests=true,"--drop-declared"=>drop_declared=true,_=>return Err(invalid("unsupported native FIX option; no legacy fallback"))}}
 // Legacy fix_cli tests drop-declared before the tests switch.
let root=std::fs::canonicalize(crate::cli_arguments::find_root(parsed.root))?;Ok(Invocation{program:program.ok_or_else(||invalid("native FIX needs --native-dmbc ABSOLUTE_EXE"))?,root,prefixes,apply,mode:if drop_declared{Mode::TrackedDropDeclared}else if tests{Mode::TrackedTests}else{Mode::Tracked}})
}
#[derive(Debug)]struct CommitFailure{commit:Option<u64>,verified:bool,primary:io::Error}
impl std::fmt::Display for CommitFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self.commit{Some(value)if self.verified=>write!(f,"native FIX {value} file(s) committed; delivery failed: {}",self.primary),Some(value)=>write!(f,"native FIX remote header claims {value} file(s) committed; report is unverified: {}",self.primary),None=>write!(f,"native FIX commit status unknown; source may have changed; delivery failed: {}",self.primary)}}}
impl std::error::Error for CommitFailure{fn source(&self)->Option<&(dyn std::error::Error+'static)>{Some(&self.primary)}}
fn failure(primary:io::Error,commit:Option<u64>,verified:bool)->io::Error{if primary.get_ref().is_some_and(|error|error.is::<CommitFailure>()){return primary}io::Error::new(primary.kind(),CommitFailure{commit,verified,primary})}
struct Delivered<'a>{diagnostics:&'a[u8],report:&'a[u8],committed:u64}
fn text<'a>(bytes:&'a[u8],status:i32,request:&Invocation,work:&NativeReportWork,opstderr:&[u8])->io::Result<Delivered<'a>>{
 if status!=0{return Err(invalid("native FIX did not complete"))}let line=bytes.iter().take(MAX_HEADER).position(|b|*b==b'\n').ok_or_else(||invalid("native FIX lacks bounded completed header"))?;work.temporary(0,MAX_HEADER.checked_mul(8).and_then(|n|n.checked_add(65536)).ok_or_else(||work.overflow())?)?;
 let terminal:Terminal=serde_json::from_slice(&bytes[..line]).map_err(io::Error::other)?;terminal.require(&request.root,&request.prefixes,request.mode,request.apply)?;let payload_result=(||->io::Result<Delivered<'a>>{let payload=&bytes[line+1..];let dn=usize::try_from(terminal.diagnostics.as_ref().map_or(0,|s|s.length)).map_err(|_|invalid("native FIX diagnostic length overflow"))?;let rn=usize::try_from(terminal.report.length).map_err(|_|invalid("native FIX report length overflow"))?;if dn.checked_add(rn)!=Some(payload.len()){return Err(invalid("native FIX delivered stream extents differ"))}let(diagnostics,report)=payload.split_at(dn);
 if terminal.diagnostics.as_ref().is_some_and(|seal|seal.hash.0!=xxhash_rust::xxh3::xxh3_128(diagnostics))||terminal.report.hash.0!=xxhash_rust::xxh3::xxh3_128(report)||!report.ends_with(b"\n")||std::str::from_utf8(report).is_err(){return Err(invalid("native FIX delivered streams differ from actual seals/text"))}if !opstderr.is_empty(){return Err(failure(io::Error::new(io::ErrorKind::Unsupported,"operational stderr has no separately qualified log sink; no completed semantic output delivered"),Some(terminal.committed_files),true))}Ok(Delivered{diagnostics,report,committed:terminal.committed_files})})();payload_result.map_err(|error|failure(error,Some(terminal.committed_files),false))
}
fn publish(delivered:Delivered<'_>,output:&mut impl Write,diagnostics:&mut impl Write)->io::Result<()>{diagnostics.write_all(delivered.diagnostics).and_then(|()|output.write_all(delivered.report)).map_err(|error|failure(error,Some(delivered.committed),true))}
fn run(args:&[String],output:&mut impl Write,diagnostics:&mut impl Write)->io::Result<u8>{let request=invocation(args)?;let mut command=Command::new(&request.program);command.arg("analyze-fix").arg("--workspace").arg(&request.root);for prefix in &request.prefixes{command.arg("--path").arg(prefix);}if request.apply{command.arg("--apply");}match request.mode{Mode::TrackedTests=>{command.arg("--tests");},Mode::TrackedDropDeclared=>{command.arg("--drop-declared");},_=>{}}
 let(status,captured,stderr)=capture_command(command,OUTER_WATCHDOG,policy_stdout_work,|r|bounded(r,MAX_STDERR)).map_err(|error|failure(error,None,false))?;diagnostics.write_all(&stderr).map_err(|error|failure(error,None,false))?;let Some(0)=status.code()else{return Ok(if status.code()==Some(75){75}else{2})};let work=captured.policy_work.as_ref().ok_or_else(||failure(invalid("native FIX output lost physical allowance"),None,false))?;let delivered=text(&captured.bytes,0,&request,work,&stderr).map_err(|error|failure(error,None,false))?;publish(delivered,output,diagnostics)?;Ok(0)
}
pub(super)fn cli(args:&[String])->std::process::ExitCode{match run(args,&mut io::stdout().lock(),&mut io::stderr().lock()){Ok(code)=>std::process::ExitCode::from(code),Err(error)=>{eprintln!("analyze native FIX: {error}");std::process::ExitCode::from(2)}}}


#[cfg(test)]mod tests{use super::*;
 #[test]fn native_fix_client_preterminal_failures_keep_unknown_commit_and_first_io(){
 for primary in [io::Error::from_raw_os_error(1450),invalid("native FIX output lost physical allowance")]{let expected=primary.kind();let raw=primary.raw_os_error();let error=failure(primary,None,false);assert_eq!(error.kind(),expected);let status=error.get_ref().unwrap().downcast_ref::<CommitFailure>().unwrap();assert_eq!(status.commit,None);assert!(!status.verified);assert_eq!(status.primary.raw_os_error(),raw);assert!(error.to_string().contains("source may have changed"));}
 }
 #[test]fn native_fix_client_preserves_full_root_repeated_prefix_and_legacy_flag_precedence_without_fallback(){
 let exe=if cfg!(windows){"E:/actual/dmbc.exe"}else{"/actual/dmbc"};let root=std::env::current_dir().unwrap();let mut args=vec!["fix".into(),"--native-dmbc".into(),exe.into(),"--root".into(),root.to_string_lossy().into_owned()];let all=invocation(&args).unwrap();assert!(all.prefixes.is_empty());assert_eq!(all.mode,Mode::Tracked);args.extend(["--path".into(),"code/one".into(),"--path".into(),"maps/two".into(),"--apply".into(),"--apply".into(),"--tests".into()]);let selected=invocation(&args).unwrap();assert_eq!(selected.prefixes,["code/one","maps/two"]);assert!(selected.apply);assert_eq!(selected.mode,Mode::TrackedTests);args.push("--drop-declared".into());assert_eq!(invocation(&args).unwrap().mode,Mode::TrackedDropDeclared);args.extend(["--lint".into(),"untyped".into()]);assert_eq!(invocation(&args).unwrap().mode,Mode::TrackedDropDeclared,"legacy main ignores lint selectors for fix");args.push("--unknown-fix-mode".into());assert!(invocation(&args).is_err());
 }
 #[test]fn native_fix_client_seals_both_streams_and_keeps_verified_or_claimed_commit_evidence_on_errors(){
 use crate::{native_fix_wire::{Terminal,Schema,Scope},selected_exclusions_wire::{Frame,Hex128,Seal}};let root=if cfg!(windows){PathBuf::from("E:/project")}else{PathBuf::from("/project")};let request=Invocation{program:root.join("dmbc"),root,prefixes:Vec::new(),apply:true,mode:Mode::Tracked};let report=b"2 rewrite(s) applied, 0 for hand conversion\n";let diagnostics=b"actual diagnostic\n";let t=Terminal{schema:Schema::V1,complete:true,full_policy_parity:false,root:request.root.clone(),scope:Scope::AllTrackedSources,prefixes:Vec::new(),mode:request.mode,apply:true,frame:Frame{semantic_revision:Hex128(1),source_revision:Hex128(2),policy_revision:Hex128(3)},selected:3,visited:3,rewrites:2,residue:0,committed_files:2,diagnostics:Some(Seal{length:diagnostics.len()as u64,hash:Hex128(xxhash_rust::xxh3::xxh3_128(diagnostics))}),report:Seal{length:report.len()as u64,hash:Hex128(xxhash_rust::xxh3::xxh3_128(report))}};let encode=|t:&Terminal,d:&[u8],r:&[u8]|{let mut bytes=serde_json::to_vec(t).unwrap();bytes.push(b'\n');bytes.extend_from_slice(d);bytes.extend_from_slice(r);bytes};let work=NativeReportWork::new();let bytes=encode(&t,diagnostics,report);let delivered=text(&bytes,0,&request,&work,&[]).unwrap();assert_eq!(delivered.diagnostics,diagnostics);assert_eq!(delivered.report,report);
 struct Stop;impl Write for Stop{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let error=publish(delivered,&mut Stop,&mut io::sink()).unwrap_err();let status=error.get_ref().unwrap().downcast_ref::<CommitFailure>().unwrap();assert_eq!(status.commit,Some(2));assert!(status.verified);assert_eq!(status.primary.raw_os_error(),Some(1450));
 let error=text(&bytes,0,&request,&work,b"operational trace\n").err().unwrap();let status=error.get_ref().unwrap().downcast_ref::<CommitFailure>().unwrap();assert_eq!(status.commit,Some(2));assert!(status.verified);assert!(text(&bytes,1,&request,&work,&[]).is_err());let mut corrupt=report.to_vec();corrupt[0]^=1;let error=text(&encode(&t,diagnostics,&corrupt),0,&request,&work,&[]).err().unwrap();let status=error.get_ref().unwrap().downcast_ref::<CommitFailure>().unwrap();assert_eq!(status.commit,Some(2));assert!(!status.verified);assert!(text(&encode(&t,b"",report),0,&request,&work,&[]).is_err());let mut wrong=t;wrong.visited=2;assert!(text(&encode(&wrong,diagnostics,report),0,&request,&work,&[]).is_err());
 }
}
